INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine API immer nötig, um die UI mit dem Backend zu verbinden?', 2, '[{"text": "Nein", "correct": true, "because": "Direkte Methoden wie WebSockets möglich"}, {"text": "Ja", "correct": false, "because": "Alternativen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der UI-Backend-Verbindung?', 3, '[{"text": "Dynamische Datenanzeige", "correct": true, "because": "UI zeigt Backend-Daten"}, {"text": "Datenkompression", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Builds", "correct": false, "because": "Pipeline-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien nutze ich für eine UI-Backend-Integration?', 5, '[{"text": "REST-API", "correct": true, "because": "Standard für Datenabfrage"}, {"text": "AJAX", "correct": true, "because": "Asynchrone Updates"}, {"text": "Static HTML", "correct": false, "because": "Keine Dynamik"}, {"text": "High DPI", "correct": false, "because": "Kein Verbindungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) AJAX ermöglicht asynchrone Updates. b) REST ist nur für Webseiten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "REST auch für Apps"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der UI-Backend-Verbindung?', 4, '[{"text": "Datenformat", "correct": false, "because": "JSON/XML entscheidend"}, {"text": "API-Endpunkte", "correct": false, "because": "Verbindungsziele"}, {"text": "Farbdesign", "correct": true, "because": "Kein Verbindungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob AJAX auch ohne JavaScript funktioniert?', 2, '[{"text": "Nein", "correct": true, "because": "JavaScript ist Kern von AJAX"}, {"text": "Ja", "correct": false, "because": "Ohne JS keine Asynchronität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für eine einfache UI-Datenabfrage?', 3, '[{"text": "REST GET", "correct": true, "because": "Einfach und standardisiert"}, {"text": "SOAP", "correct": false, "because": "Komplexer"}, {"text": "FTP", "correct": false, "because": "Dateiübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für eine UI-Backend-Verbindung essenziell?', 5, '[{"text": "HTTP-Anfragen", "correct": true, "because": "Grundlage der Kommunikation"}, {"text": "Datenparsing", "correct": true, "because": "Verarbeitet Antworten"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Hardware-aspekt"}, {"text": "Statische Seiten", "correct": false, "because": "Keine Dynamik"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) REST-APIs sind zustandslos. b) AJAX ist nur für Webseiten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "AJAX auch in Apps"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine UI-Backend-Verbindung?', 4, '[{"text": "API-Endpunkt", "correct": false, "because": "Verbindungsweg"}, {"text": "Datenformat", "correct": false, "because": "Kommunikationsbasis"}, {"text": "3D-Animationen", "correct": true, "because": "Kein Verbindungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist REST nur für Datenabfragen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch POST, PUT, DELETE"}, {"text": "Ja", "correct": false, "because": "Vielseitiger als nur GET"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken verbessern die UI-Backend-Integration?', 4, '[{"text": "WebSockets", "correct": true, "because": "Echtzeitkommunikation"}, {"text": "AJAX", "correct": true, "because": "Asynchrone Updates"}, {"text": "Statische IPs", "correct": false, "because": "Netzwerkdetail"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass UI-Backend-Verbindungen immer langsam sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Optimierung möglich"}, {"text": "Ja", "correct": false, "because": "Abhängig von Implementierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der UI-Backend-Verbindung?', 3, '[{"text": "Antwortzeit", "correct": true, "because": "Verbessert Nutzererlebnis"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Sekundär"}, {"text": "Einfache Syntax", "correct": false, "because": "Funktion zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) REST nutzt HTTP-Methoden. b) AJAX braucht immer eine Datenbank.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "AJAX unabhängig von DB"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet AJAX für die UI-Backend-Verbindung?', 5, '[{"text": "Keine Seitenaktualisierung", "correct": true, "because": "Flüssige Nutzung"}, {"text": "Echtzeitdaten", "correct": true, "because": "Asynchrone Updates"}, {"text": "Hohe Kompression", "correct": false, "because": "Kein Kompressionsfaktor"}, {"text": "Statische Inhalte", "correct": false, "because": "Dynamik im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der UI-Backend-Verbindung unwichtig?', 3, '[{"text": "Datenkonsistenz", "correct": false, "because": "Sichert Zuverlässigkeit"}, {"text": "Fehlerbehandlung", "correct": false, "because": "Wichtig für Robustheit"}, {"text": "Blinkende Buttons", "correct": true, "because": "Kein Verbindungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich mit REST auch Daten ändern?', 3, '[{"text": "Ja", "correct": true, "because": "POST, PUT für Änderungen"}, {"text": "Nein", "correct": false, "because": "Nicht nur GET"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob WebSockets für statische Daten geeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Echtzeit ist Fokus"}, {"text": "Ja", "correct": false, "because": "Statische Daten brauchen keine WebSockets"}]');
